bash -lc python - <<'PY'
from pathlib import Path
p=Path('/mnt/data/GMRI_Counsel_Style_Revision_2026-10-24/letters')
changes={
'01_OpenAI_Notice_and_Request.md':{
'I am seeking effective access to an analytical and communication tool used to compensate for disability-related limitations, not preferential treatment based on my former occupation or unrestricted access to unrelated services.':'The relief sought concerns the functional accessibility of a research and communication service used to compensate for disability-related limitations.'},
'03_Anthropic_Notice_and_Request.md':{
'This notice concerns a present access requirement and Anthropic\'s published service rules. I am not alleging that an undocumented internal decision was made about my account or importing incidents attributed to another vendor into Anthropic\'s record.':'The determination should address an identified access requirement against Anthropic\'s own published service and data-governance rules.',
' No correspondence or evidence has been submitted on my behalf by this draft.':''},
'04_Meta_Notice_and_Request.md':{
'This is an access and configuration request, not an assertion that Meta has subjected my account to a particular undisclosed classification or that incidents documented on other platforms also occurred on Meta AI.':'The requested determination concerns Meta AI\'s own documented functions and the compatibility of private processing with durable task continuity.'},
'05_Grok_Notice_and_Request.md':{
'This is a specific request for service modification. It does not allege, without evidence, that Grok has made a diagnosis, imposed a disability-based account flag, or engaged in conduct documented on another provider\'s platform.':'The determination should address Grok\'s published consumer and API capabilities, not general assumptions about AI products.'},
}
for name,c in changes.items():
 s=(p/name).read_text()
 for a,b in c.items():
  assert a in s,(name,a)
  s=s.replace(a,b)
 (p/name).write_text(s)
print('updated',len(changes))
PY

