import zipfile, pathlib, fitz, os
z=zipfile.ZipFile('/mnt/data/GMRI_LOVE_NOTE_COLD_START_2026-10-23_FULL_WITH_SIRI_EVIDENCE(4).zip')
for name in z.namelist():
 if name.startswith('siri_evidence/') and name.endswith('.pdf'):
  out=pathlib.Path('/mnt/data/_gmri_evidence_review')/name.split('/')[-1]; out.write_bytes(z.read(name))
  d=fitz.open(str(out));tot=sum(len(p.get_text().strip()) for p in d)
  print('\n',name,'pages',len(d),'textchars',tot)
  if tot>20: print(d[0].get_text().strip()[:1400])
